patches.old:
body {
  font-family: var(--font-sans);
  background-color: #e9eeea;
  color: var(--navy);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 24px 16px;
}
/* Review & demo toolbar */
.review-header {
  width: 100%;
  max-width: 960px;
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 16px;
  margin-bottom: 20px;
  box-shadow: 0 2px 8px rgba(7, 21, 47, 0.05);
}
.review-banner {
  background: #fdf5d3;
  color: #744210;
  border: 1px solid #fae8a4;
  border-radius: 6px;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  margin-bottom: 12px;
}
.toolbar-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  justify-content: space-between;
  margin-bottom: 8px;
}
.toolbar-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--navy);
}
.btn-group {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.btn {
  appearance: none;
  border: 1px solid var(--border);
  background: #ffffff;
  color: var(--navy);
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
}
.btn:hover {
  background: #f0f4f1;
  border-color: #c4d1c8;
}
.btn.active {
  background: var(--navy);
  color: #ffffff;
  border-color: var(--navy);
}
.btn-emerald {
  background: var(--emerald-start);
  color: #ffffff;
  border-color: var(--emerald-start);
}
.btn-emerald:hover {
  background: var(--emerald-end);
}
.state-info-badge {
  font-size: 11.5px;
  color: var(--navy-muted);
  background: #f4f6f5;
  padding: 3px 8px;
  border-radius: 4px;
  border: 1px solid #e1e7e3;
  font-family: monospace;
}

/* Phone container */
.phone-viewport {
  width: 372px;
  height: 732px;
  min-width: 372px;
  min-height: 732px;
  max-width: 372px;
  max-height: 732px;
  background: #ffffff;
  border-radius: 44px;
  box-shadow: 0 16px 40px rgba(7, 21, 47, 0.15), 0 0 0 10px #1a2332;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* Capture mode: strict 0,0 positioning, no frame, no toolbar */
body.capture-mode {
  padding: 0 !important;
  margin: 0 !important;
  background: #ffffff !important;
  overflow: hidden !important;
}
body.capture-mode .review-header,
body.capture-mode .state-inspector-panel {
  display: none !important;
}
body.capture-mode .phone-viewport {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 0 !important;
  width: 372px !important;
  height: 732px !important;
}

