  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transform-origin: top center;
}

/* Responsive normal mode: fit 320px, 372px, 375px, 430px viewports without horizontal clipping/scrolling */
@media (max-width: 410px) {
  body {
    padding: 12px 6px;
  }
  .review-header {
    padding: 10px 8px;
    margin-bottom: 12px;
  }
  .toolbar-row {
    gap: 6px;
  }
  .toolbar-title {
    font-size: 13px;
  }
  .btn {
    padding: 4px 7px;
    font-size: 11.5px;
  }
  .btn-group {
    gap: 4px;
  }
  .phone-viewport {
    min-width: unset;
    max-width: 100%;
    zoom: 0.82;
    zoom: calc((100vw - 16px) / 392);
  }
}
@media (max-width: 350px) {
  body {
    padding: 8px 4px;
  }
  .review-header {
    padding: 8px 6px;
    margin-bottom: 8px;
  }
  .toolbar-title {
    font-size: 12px;
  }
  .btn {
    padding: 4px 6px;
    font-size: 11px;
  }
  .state-info-badge {
    font-size: 10.5px;
    padding: 2px 5px;
  }
  .phone-viewport {
    min-width: unset;
    max-width: 100%;
    zoom: 0.74;
    zoom: calc((100vw - 12px) / 392);
  }
}

