  margin: 0 !important;
  width: 372px !important;
  height: 732px !important;
  min-width: 372px !important;
  min-height: 732px !important;
  max-width: 372px !important;
  max-height: 732px !important;
  zoom: 1 !important;
  transform: none !important;
}
